import sys
import heapq

def main():
    import sys
    import heapq

    def read_ints():
        return list(map(int, sys.stdin.readline().split()))

    n, m = read_ints()
    a = read_ints()
    c = read_ints()

    # Priority queue to store available dishes by cost and index
    available_dishes = []
    for i in range(n):
        if a[i] > 0:
            heapq.heappush(available_dishes, (c[i], i))

    results = []

    for _ in range(m):
        t_j, d_j = read_ints()
        t_j -= 1  # Convert to 0-based index

        cost = 0
        while d_j > 0:
            if a[t_j] > 0:
                # Serve the requested dish
                cost += c[t_j]
                a[t_j] -= 1
                d_j -= 1
            else:
                # Serve the cheapest available dish
                if available_dishes:
                    min_cost, min_index = heapq.heappop(available_dishes)
                    cost += min_cost
                    a[min_index] -= 1
                    d_j -= 1
                    if a[min_index] > 0:
                        heapq.heappush(available_dishes, (min_cost, min_index))
                else:
                    # No more dishes available
                    break

        results.append(cost)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
